window.KV_LESSONS.push(
{
  "id":"social-science.cbse6.exploring-society.ch1.maps-components.v1",
  "title":"Locating Places on the Earth — Read Maps with Purpose",
  "subject":"Social Science",
  "worldId":"geography",
  "topic":"CBSE Class 6 · Exploring Society: India and Beyond · Chapter 1",
  "subtopic":"Maps, scale, direction and symbols",
  "ageBand":"11-13",
  "difficulty":"Foundational",
  "learningObjective":"Use a map's scale, direction and symbols together to describe where a place is and how one location relates to another.",
  "content":"A map is a model of part of the Earth's surface viewed from above. It reduces a large real area so we can reason about location and movement on a page or screen. Three ideas make a map useful: scale connects map distance with real distance; direction tells how places lie relative to one another; and symbols represent features without drawing them at full size. These components answer different questions, so a careful reader checks all three instead of relying on appearance alone. A route that looks short on a map may still represent a long real distance, and a symbol only has meaning when we know what it stands for. Different maps can also emphasise different information, so the first step is to ask what the map is designed to show.",
  "workedExample":"A simple town map shows the library 3 cm east of the station. The scale says 1 cm represents 500 m. Multiplying 3 by 500 gives 1,500 m, or 1.5 km. The compass direction tells us the library is east of the station, while the library symbol identifies the destination. All three map components contribute a different part of the answer.",
  "board":"CBSE","classLevel":6,"curriculumSession":"2026-27","book":"Exploring Society: India and Beyond","chapter":1,"chapterTitle":"Locating Places on the Earth","topicId":"TOPIC-SOC6-01-01",
  "sourceRefs":["NCERT-EXPLORING-SOCIETY-G6-2026-27-CH1","KVS-SOC6-CH1-ORIGINAL-MAPS"],
  "rightsStatus":"KIRTHIVERSE_ORIGINAL_NO_TEXTBOOK_PROSE_OR_EXERCISE_REPRODUCTION",
  "schoolOverlay":"SAN Academy Tambaram","schoolMappingStatus":"VALIDATION_CONTEXT_ONLY_NO_SCHOOL_PACING_OR_EDITION_CLAIM",
  "kikiTeaching":{"objective":"Student combines scale, direction and symbols to interpret a simple unfamiliar map.","intro":"I’m Kiki, your KirthiVerse guide. A map is not just a picture: it is a compact system for answering where, how far and in which direction.","priorKnowledge":"Describe the position of one familiar place relative to another using a direction word such as north, south, east or west.","visualIdea":"Use a three-part map decoder: Scale = how far, Compass = which direction, Legend = what the symbols mean.","misconceptionCheck":"The visual length of a route is not the real-world distance until the map scale is applied.","recap":"Identify the map's purpose, read the scale, check direction and decode symbols before drawing a conclusion.","parentPrompt":"Sketch a fictional neighbourhood on paper, add a scale, north arrow and legend, then ask the learner to explain one route without sharing a real home address."},
  "remediation":{"trigger":"Learner reads only the picture and ignores scale, direction or the legend.","strategy":"Give one tiny fictional map and require three separate answers: what a symbol means, which direction a place lies, and the real distance calculated from the scale.","masteryEvidence":"Learner independently interprets two unfamiliar fictional maps and correctly uses scale, direction and symbols to justify location and distance statements."}
},
{
  "id":"social-science.cbse6.exploring-society.ch1.coordinates.v1",
  "title":"Locating Places on the Earth — Use Latitude and Longitude",
  "subject":"Social Science","worldId":"geography","topic":"CBSE Class 6 · Exploring Society: India and Beyond · Chapter 1","subtopic":"Globe, latitude, longitude and geographic coordinates","ageBand":"11-13","difficulty":"Foundational",
  "learningObjective":"Distinguish latitude from longitude and use a latitude-longitude pair to identify a position on a globe or coordinate grid.",
  "content":"A globe represents the Earth as a sphere-like model, and imaginary reference lines help us describe positions consistently. Latitude measures how far north or south a place is from the Equator, which is 0° latitude. Lines of latitude run around the globe parallel to the Equator. Longitude measures how far east or west a place is from the Prime Meridian, which is 0° longitude; meridians run from pole to pole. A location becomes much more precise when both values are used together. The order matters: a latitude-longitude pair describes two different directions, so swapping the values can point somewhere else. Coordinates are reference information; they do not by themselves describe what a place is like on the ground.",
  "workedExample":"Suppose a practice grid marks point P at 20°N, 60°E. The first value places P north of the Equator; the second places it east of the Prime Meridian. Point Q at 20°S, 60°E shares the same longitude but lies in the opposite north-south hemisphere. Comparing one coordinate at a time shows exactly what changed.",
  "board":"CBSE","classLevel":6,"curriculumSession":"2026-27","book":"Exploring Society: India and Beyond","chapter":1,"chapterTitle":"Locating Places on the Earth","topicId":"TOPIC-SOC6-01-02","sourceRefs":["NCERT-EXPLORING-SOCIETY-G6-2026-27-CH1","KVS-SOC6-CH1-ORIGINAL-COORDINATES"],"rightsStatus":"KIRTHIVERSE_ORIGINAL_NO_TEXTBOOK_PROSE_OR_EXERCISE_REPRODUCTION","schoolOverlay":"SAN Academy Tambaram","schoolMappingStatus":"VALIDATION_CONTEXT_ONLY_NO_SCHOOL_PACING_OR_EDITION_CLAIM",
  "kikiTeaching":{"objective":"Student identifies latitude and longitude correctly and interprets a coordinate pair without reversing the axes or hemispheres.","intro":"Coordinates give Earth a shared reference grid. Kiki keeps two questions separate: how far north or south, and how far east or west.","priorKnowledge":"On a simple square grid, describe how a row-and-column pair helps locate one exact cell.","visualIdea":"Use two colour-neutral guide arrows: Equator → north/south for latitude; Prime Meridian → east/west for longitude.","misconceptionCheck":"Latitude is not east-west position and longitude is not north-south position; the line's direction is different from what the value measures.","recap":"Latitude references the Equator, longitude references the Prime Meridian, and both together locate a position.","parentPrompt":"Use an imaginary globe grid or printed coordinate worksheet. Avoid asking the learner to reveal or upload their precise real-world location."},
  "remediation":{"trigger":"Learner swaps latitude and longitude, omits N/S/E/W, or assumes one coordinate is enough for a precise global position.","strategy":"Sort six coordinate cards into north/south and east/west clues, then reconstruct three complete coordinate pairs and point to the matching grid intersections.","masteryEvidence":"Learner correctly interprets and compares four unfamiliar coordinate pairs, explaining which hemisphere relationship changes when either latitude or longitude changes."}
},
{
  "id":"social-science.cbse6.exploring-society.ch1.time-longitude.v1",
  "title":"Locating Places on the Earth — Connect Longitude and Time",
  "subject":"Social Science","worldId":"geography","topic":"CBSE Class 6 · Exploring Society: India and Beyond · Chapter 1","subtopic":"Local time, standard time and time zones","ageBand":"11-13","difficulty":"Foundational",
  "learningObjective":"Explain why local time varies with longitude and why countries use standard time or multiple time zones for practical coordination.",
  "content":"The Earth rotates once in about 24 hours, so places at different longitudes face the Sun at different times. This creates differences in local solar time. If every town used only its own local time, transport, communication and shared schedules would become difficult. Countries therefore adopt standard time based on selected reference meridians, and very wide countries may use several time zones. A useful approximate relationship comes from one full rotation: 360° in 24 hours means about 15° of longitude per hour, or about 1° in four minutes. Moving east generally corresponds to a later local time and moving west to an earlier one. Political boundaries make real time-zone maps more complicated than perfectly straight longitude strips, so longitude explains the geographic principle while official time-zone rules determine the clocks people actually use.",
  "workedExample":"Two imaginary places lie at 30°E and 45°E. Their longitude difference is 15°. Since 15° corresponds to about one hour of rotation, the place at 45°E has a local solar time about one hour ahead of the place at 30°E. This is a geographic calculation; an actual country's official clock time still follows its legally adopted time zone.",
  "board":"CBSE","classLevel":6,"curriculumSession":"2026-27","book":"Exploring Society: India and Beyond","chapter":1,"chapterTitle":"Locating Places on the Earth","topicId":"TOPIC-SOC6-01-03","sourceRefs":["NCERT-EXPLORING-SOCIETY-G6-2026-27-CH1","KVS-SOC6-CH1-ORIGINAL-TIME"],"rightsStatus":"KIRTHIVERSE_ORIGINAL_NO_TEXTBOOK_PROSE_OR_EXERCISE_REPRODUCTION","schoolOverlay":"SAN Academy Tambaram","schoolMappingStatus":"VALIDATION_CONTEXT_ONLY_NO_SCHOOL_PACING_OR_EDITION_CLAIM",
  "kikiTeaching":{"objective":"Student relates a longitude difference to approximate local-time difference and distinguishes local solar time from an official standard time zone.","intro":"Earth keeps turning, so noon does not happen everywhere at once. Standard time is a human coordination system built on that geographic reality.","priorKnowledge":"Explain why two places far apart east-to-west might see sunrise at different clock-independent moments.","visualIdea":"Use a rotating globe strip marked every 15°: each 15° step corresponds to roughly one hour of local-time difference.","misconceptionCheck":"Longitude helps explain local solar time, but official time zones are not always exact 15° strips and may follow national or regional boundaries.","recap":"Earth's rotation creates local-time differences; standard time zones make shared schedules practical.","parentPrompt":"Use fictional longitudes or public city time-zone examples. Do not ask for the learner's live device location or home coordinates."},
  "remediation":{"trigger":"Learner links time difference to latitude, reverses east/west time direction, or assumes every country has exactly one perfectly straight 15° time zone.","strategy":"Use four fictional longitude pairs, calculate each angular difference, convert using 15° ≈ 1 hour, then separately label whether the result is local-time reasoning or an official time-zone rule.","masteryEvidence":"Learner solves three unfamiliar longitude/time comparisons and explains in their own words why standard time can differ from purely local solar time."}
},
{
  "id":"social-science.cbse6.exploring-society.ch2.land-water.v1",
  "title":"Oceans and Continents — See Earth's Land–Water Pattern",
  "subject":"Social Science","worldId":"geography","topic":"CBSE Class 6 · Exploring Society: India and Beyond · Chapter 2","subtopic":"Land and water distribution","ageBand":"11-13","difficulty":"Foundational",
  "learningObjective":"Explain that water covers much more of Earth's surface than land and compare the broad land-water pattern of the Northern and Southern Hemispheres.",
  "content":"Earth is often called the blue planet because most of its surface is covered by water. Land occupies a much smaller share. That pattern is not distributed evenly: the Northern Hemisphere contains a larger share of the world's major landmasses, while the Southern Hemisphere has a greater dominance of ocean area. The important idea is the pattern rather than memorising a single percentage. Maps and globes help us compare how land and water are arranged and how that arrangement shapes travel, climate, habitats and human settlement. A hemisphere comparison is a broad geographic observation, not a claim that one half of Earth contains only land or only water.",
  "workedExample":"Imagine two equal-area globe views, one centred on the Northern Hemisphere and one on the Southern Hemisphere. If the northern view shows many large connected land areas while the southern view shows more continuous ocean, the correct conclusion is that both hemispheres contain land and water, but their proportions differ noticeably.",
  "board":"CBSE","classLevel":6,"curriculumSession":"2026-27","book":"Exploring Society: India and Beyond","chapter":2,"chapterTitle":"Oceans and Continents","topicId":"TOPIC-SOC6-02-01","sourceRefs":["NCERT-EXPLORING-SOCIETY-G6-2026-27-CH2","KVS-CBSE6-SOC-CH2-SOURCE-TOPIC-V1"],"rightsStatus":"KIRTHIVERSE_ORIGINAL_NO_TEXTBOOK_PROSE_OR_EXERCISE_REPRODUCTION","schoolOverlay":"SAN Academy Tambaram","schoolMappingStatus":"VALIDATION_CONTEXT_ONLY_NO_SCHOOL_PACING_OR_EDITION_CLAIM",
  "kikiTeaching":{"objective":"Student describes the global land-water pattern and compares broad hemisphere differences without overgeneralising.","intro":"Kiki starts with the biggest pattern on Earth: water dominates the surface, but land and water are arranged differently across the two hemispheres.","priorKnowledge":"Identify land and water on a simple globe or world map.","visualIdea":"Use two simplified hemisphere circles and shade only broad land versus water areas, not political borders.","misconceptionCheck":"The Southern Hemisphere is not all ocean and the Northern Hemisphere is not all land; both contain both, in different proportions.","recap":"Water covers most of Earth, land covers less, and the hemispheres show different broad proportions.","parentPrompt":"Use a printed or offline world map and ask the learner to compare broad land-water patterns without sharing any real location."},
  "remediation":{"trigger":"Learner says one hemisphere contains only land or only water, or treats a visual map area as an exact percentage measurement.","strategy":"Sort eight labelled examples into land or water, then compare two simplified hemisphere diagrams and write one cautious sentence using words such as more, less and mostly.","masteryEvidence":"Learner independently explains the global pattern and makes two accurate hemisphere comparisons without absolute or unsupported percentage claims."}
},
{
  "id":"social-science.cbse6.exploring-society.ch2.five-oceans.v1",
  "title":"Oceans and Continents — Connect the Five Oceans",
  "subject":"Social Science","worldId":"geography","topic":"CBSE Class 6 · Exploring Society: India and Beyond · Chapter 2","subtopic":"Five oceans and their interconnection","ageBand":"11-13","difficulty":"Foundational",
  "learningObjective":"Identify the five named oceans and explain why they are understood as connected parts of one global ocean system.",
  "content":"Geographers commonly name five oceans: Pacific, Atlantic, Indian, Southern and Arctic. These names help people describe enormous regions of the world map, but the water itself is connected. Ocean boundaries are therefore useful geographic conventions rather than walls in the sea. The Pacific is the largest named ocean area, while the Arctic is the smallest. Smaller terms such as sea, gulf and bay describe water bodies with different relationships to surrounding land, but all can connect into the wider ocean system. The key Class 6 idea is to locate the five oceans and understand both the usefulness and the limits of their named boundaries.",
  "workedExample":"Trace a possible sea route on a world map from the Indian Ocean around southern Africa into the Atlantic. The ship does not cross a physical wall where one ocean name changes to another; the labels change because people divide the connected global ocean into useful named regions.",
  "board":"CBSE","classLevel":6,"curriculumSession":"2026-27","book":"Exploring Society: India and Beyond","chapter":2,"chapterTitle":"Oceans and Continents","topicId":"TOPIC-SOC6-02-02","sourceRefs":["NCERT-EXPLORING-SOCIETY-G6-2026-27-CH2","KVS-CBSE6-SOC-CH2-SOURCE-TOPIC-V1"],"rightsStatus":"KIRTHIVERSE_ORIGINAL_NO_TEXTBOOK_PROSE_OR_EXERCISE_REPRODUCTION","schoolOverlay":"SAN Academy Tambaram","schoolMappingStatus":"VALIDATION_CONTEXT_ONLY_NO_SCHOOL_PACING_OR_EDITION_CLAIM",
  "kikiTeaching":{"objective":"Student names and broadly locates all five oceans and explains their physical interconnection.","intro":"Ocean names organise the map, but Earth's seawater forms one connected system. Kiki separates labels from physical barriers.","priorKnowledge":"Point to a large body of salt water on a world map and explain how it differs from land.","visualIdea":"Use a world outline with five label zones and arrows crossing the named boundaries to show connected water.","misconceptionCheck":"The five oceans are not five sealed containers; their named boundaries do not stop water or ships.","recap":"Pacific, Atlantic, Indian, Southern and Arctic are useful named regions within a connected global ocean.","parentPrompt":"On an offline atlas, ask the learner to name oceans touching two different continents and explain how the waters connect."},
  "remediation":{"trigger":"Learner omits an ocean, places one on the wrong side of a continent, or treats named boundaries as physical barriers.","strategy":"Use a blank world outline and five movable ocean labels; place them relative to continents, then draw arrows showing where the named regions connect.","masteryEvidence":"Learner correctly labels all five oceans on an unfamiliar simplified map and explains in one clear paragraph why the ocean system is interconnected."}
},
{
  "id":"social-science.cbse6.exploring-society.ch2.continents-islands.v1",
  "title":"Oceans and Continents — Compare Continents and Islands",
  "subject":"Social Science","worldId":"geography","topic":"CBSE Class 6 · Exploring Society: India and Beyond · Chapter 2","subtopic":"Continents, islands and counting conventions","ageBand":"11-13","difficulty":"Foundational",
  "learningObjective":"Identify the seven commonly taught continents, distinguish continents from islands, and recognise that continent counts can vary by convention.",
  "content":"A continent is one of Earth's very large land regions. A widely used school convention names seven: Asia, Africa, North America, South America, Antarctica, Europe and Australia. Asia is the largest by area and Australia is the smallest of the seven-continent convention. An island is a land area surrounded by water, usually much smaller than a continent. Geographic naming is partly conventional: some traditions combine Europe and Asia as Eurasia, or North and South America as one America, so the number of continents taught can vary. For this Class 6 slice, seven is the working school convention while learners should understand that other counting systems exist.",
  "workedExample":"Suppose a learner sees a map that labels Europe and Asia separately while another source labels Eurasia as one landmass. The maps are not automatically contradictory; they may be using different continent conventions. The learner should identify the convention before comparing the count.",
  "board":"CBSE","classLevel":6,"curriculumSession":"2026-27","book":"Exploring Society: India and Beyond","chapter":2,"chapterTitle":"Oceans and Continents","topicId":"TOPIC-SOC6-02-03","sourceRefs":["NCERT-EXPLORING-SOCIETY-G6-2026-27-CH2","KVS-CBSE6-SOC-CH2-SOURCE-TOPIC-V1"],"rightsStatus":"KIRTHIVERSE_ORIGINAL_NO_TEXTBOOK_PROSE_OR_EXERCISE_REPRODUCTION","schoolOverlay":"SAN Academy Tambaram","schoolMappingStatus":"VALIDATION_CONTEXT_ONLY_NO_SCHOOL_PACING_OR_EDITION_CLAIM",
  "kikiTeaching":{"objective":"Student identifies seven commonly taught continents, distinguishes island from continent, and recognises counting conventions.","intro":"Kiki treats continent names as a useful way to organise Earth's major land regions, while remembering that counting systems are conventions.","priorKnowledge":"Distinguish a large land area from surrounding water on a world map.","visualIdea":"Use seven labelled land cards plus one separate card that says convention can change the count.","misconceptionCheck":"A different continent count does not necessarily mean the geography is wrong; it may reflect a different naming convention.","recap":"Seven continents is the working school convention here; islands are smaller land areas surrounded by water, and other continent-count conventions exist.","parentPrompt":"Use an offline atlas to locate the seven commonly taught continents, then compare one island without requiring any personal-location information."},
  "remediation":{"trigger":"Learner confuses an island with a continent, cannot identify major continents, or assumes every source must use exactly seven.","strategy":"Sort land-region cards into seven-continent labels, island examples and alternative-convention notes, then explain one difference between category and convention.","masteryEvidence":"Learner labels the seven continents, correctly classifies unfamiliar island examples, and explains why another source might legitimately use a different continent count."}
},
{
  "id":"social-science.cbse6.exploring-society.ch2.oceans-matter.v1",
  "title":"Oceans and Continents — Explain Why Oceans Matter",
  "subject":"Social Science","worldId":"geography","topic":"CBSE Class 6 · Exploring Society: India and Beyond · Chapter 2","subtopic":"Ocean life, climate influence, human impact and protection","ageBand":"11-13","difficulty":"Foundational",
  "learningObjective":"Explain two major ways oceans support life and human systems, then connect human activity to practical protection choices.",
  "content":"Oceans are more than empty spaces between continents. They provide habitats for enormous numbers of organisms, support food webs and livelihoods, and strongly influence Earth's climate by storing and moving heat and exchanging water with the atmosphere. Human activities can damage ocean environments through pollution, excessive waste, habitat destruction and unsustainable resource use. Protection therefore requires actions at several levels: individuals can reduce litter and unnecessary plastic use; communities can improve waste handling; governments and organisations can protect habitats and regulate harmful activity. At this level, the aim is to connect ocean importance with responsible choices rather than introduce advanced marine chemistry or detailed ocean-current science.",
  "workedExample":"A coastal town finds that plastic waste from streets is reaching the sea after rain. A useful response is not just a beach clean-up: preventing litter, improving bins and drainage filters, educating residents and enforcing waste rules all address different stages of the same problem.",
  "board":"CBSE","classLevel":6,"curriculumSession":"2026-27","book":"Exploring Society: India and Beyond","chapter":2,"chapterTitle":"Oceans and Continents","topicId":"TOPIC-SOC6-02-04","sourceRefs":["NCERT-EXPLORING-SOCIETY-G6-2026-27-CH2","KVS-CBSE6-SOC-CH2-SOURCE-TOPIC-V1"],"rightsStatus":"KIRTHIVERSE_ORIGINAL_NO_TEXTBOOK_PROSE_OR_EXERCISE_REPRODUCTION","schoolOverlay":"SAN Academy Tambaram","schoolMappingStatus":"VALIDATION_CONTEXT_ONLY_NO_SCHOOL_PACING_OR_EDITION_CLAIM",
  "kikiTeaching":{"objective":"Student connects ocean habitats and climate influence with human impacts and layered protection actions.","intro":"Kiki asks two linked questions: what do oceans do for Earth, and what happens when human activity damages them?","priorKnowledge":"Name one living thing that depends on an aquatic habitat and one way litter can travel through the environment.","visualIdea":"Use a four-box chain: ocean role → human pressure → consequence → protection action.","misconceptionCheck":"Ocean protection is not only about cleaning beaches after pollution happens; prevention and collective rules also matter.","recap":"Oceans support life and influence climate, human activity can harm them, and protection works best through prevention plus shared action.","parentPrompt":"Choose a public ocean-protection example from a book or offline article and ask the learner to separate prevention, clean-up and policy actions."},
  "remediation":{"trigger":"Learner lists ocean benefits without linking causes and effects, or suggests only one clean-up action for every environmental problem.","strategy":"Give three fictional ocean-impact scenarios and require a cause, one likely consequence, one prevention action and one shared/community response for each.","masteryEvidence":"Learner explains at least two ocean roles and designs a balanced protection response that includes prevention, behaviour and collective action without unsupported scientific claims."}
},
{
  "id":"social-science.cbse6.exploring-society.ch3.major-landforms.v1",
  "title":"Landforms and Life — Recognise Major Landforms",
  "subject":"Social Science","worldId":"geography","topic":"CBSE Class 6 · Exploring Society: India and Beyond · Chapter 3","subtopic":"Major landforms and comparative terrain","ageBand":"11-13","difficulty":"Foundational",
  "learningObjective":"Recognise mountains, plateaus and plains from broad terrain features and explain that landform categories describe patterns rather than perfectly uniform surfaces.",
  "content":"Landforms are large natural shapes of Earth's land surface. Three major forms used in this Class 6 chapter are mountains, plateaus and plains. Mountains rise strongly above surrounding land and often have steep slopes or high relief. Plateaus are elevated areas with broad, comparatively level or gently rolling surfaces, though their edges may be steep. Plains are extensive lower-relief areas that are generally flatter than mountains and plateaus. Real landscapes can contain valleys, hills, rivers and transitional zones, so a landform label describes the dominant pattern rather than every square metre. Comparing elevation, relief, slope and surface shape helps learners classify terrain without assuming that one photograph or one feature tells the whole story.",
  "workedExample":"Three fictional terrain cards show: A, high steep ridges with deep valleys; B, a broad high surface ending in a steep edge; and C, a wide low-relief surface crossed by a river. The strongest classifications are mountain for A, plateau for B and plain for C because each decision uses several terrain clues together.",
  "board":"CBSE","classLevel":6,"curriculumSession":"2026-27","book":"Exploring Society: India and Beyond","chapter":3,"chapterTitle":"Landforms and Life","topicId":"TOPIC-SOC6-03-01","sourceRefs":["NCERT-EXPLORING-SOCIETY-G6-2026-27-CH3","KVS-CBSE6-SOC-CH3-SOURCE-TOPIC-V1"],"rightsStatus":"KIRTHIVERSE_ORIGINAL_NO_TEXTBOOK_PROSE_OR_EXERCISE_REPRODUCTION","schoolOverlay":"SAN Academy Tambaram","schoolMappingStatus":"VALIDATION_CONTEXT_ONLY_NO_SCHOOL_PACING_OR_EDITION_CLAIM",
  "kikiTeaching":{"objective":"Student classifies unfamiliar terrain as mountain, plateau or plain using more than one physical clue.","intro":"Kiki reads a landscape like evidence: how high is it, how steep is it, and what is the overall surface shape?","priorKnowledge":"Describe whether a simple surface is high or low, steep or gentle, and flat or uneven.","visualIdea":"Use three silhouette cards labelled high-and-steep, high-and-broad, and low-relief-and-wide, then compare exceptions.","misconceptionCheck":"A plain is not perfectly flat everywhere, and a plateau is not simply any hill with a flat top.","recap":"Mountains, plateaus and plains are broad landform patterns identified by elevation, relief, slope and surface shape.","parentPrompt":"Compare public landscape photographs or offline atlas images and ask for evidence-based classification without using the learner's real location."},
  "remediation":{"trigger":"Learner classifies landforms from one visual cue only or assumes every example must look identical to a textbook diagram.","strategy":"Provide six fictional terrain profiles and require two clues for every classification, including one ambiguous transitional example that needs a cautious answer.","masteryEvidence":"Learner correctly classifies four unfamiliar terrain examples and justifies each using at least two physical characteristics rather than a memorised picture."}
},
{
  "id":"social-science.cbse6.exploring-society.ch3.mountains-life.v1",
  "title":"Landforms and Life — Understand Mountains and Human Choices",
  "subject":"Social Science","worldId":"geography","topic":"CBSE Class 6 · Exploring Society: India and Beyond · Chapter 3","subtopic":"Mountains, opportunities, constraints and adaptation","ageBand":"11-13","difficulty":"Foundational",
  "learningObjective":"Explain how steep terrain and elevation can create both opportunities and challenges for transport, settlement, water, farming and livelihoods without treating mountain communities as all the same.",
  "content":"Mountain environments influence human activity because steep slopes, elevation, climate and access can differ sharply over short distances. Roads and buildings may be harder or more expensive to construct, and farming may require terraces or small suitable areas rather than broad fields. At the same time, mountains can provide water sources, forests, grazing areas, tourism opportunities, distinctive crops and cultural landscapes. These are possibilities, not rules: two mountain communities can organise work and settlement very differently depending on climate, technology, markets, local knowledge and public services. Geography helps explain constraints and opportunities, but it should never be used to stereotype what people must do.",
  "workedExample":"A fictional mountain village needs a safer route to a clinic. A straight road would cross a very steep slope, so planners compare a longer gentler route, a bridge across a narrow valley and improved emergency transport. The terrain shapes the options, but people still make choices using technology, cost, safety and local priorities.",
  "board":"CBSE","classLevel":6,"curriculumSession":"2026-27","book":"Exploring Society: India and Beyond","chapter":3,"chapterTitle":"Landforms and Life","topicId":"TOPIC-SOC6-03-02","sourceRefs":["NCERT-EXPLORING-SOCIETY-G6-2026-27-CH3","KVS-CBSE6-SOC-CH3-SOURCE-TOPIC-V1"],"rightsStatus":"KIRTHIVERSE_ORIGINAL_NO_TEXTBOOK_PROSE_OR_EXERCISE_REPRODUCTION","schoolOverlay":"SAN Academy Tambaram","schoolMappingStatus":"VALIDATION_CONTEXT_ONLY_NO_SCHOOL_PACING_OR_EDITION_CLAIM",
  "kikiTeaching":{"objective":"Student links mountain terrain to at least one challenge and one opportunity while preserving human choice and variation.","intro":"Mountains change the problem-solving conditions, not the abilities or choices of the people who live there.","priorKnowledge":"Explain how a steep path differs from a level path for walking, carrying goods or building a road.","visualIdea":"Use a balance chart with terrain constraint on one side and adaptation or opportunity on the other.","misconceptionCheck":"Mountain geography does not determine one fixed occupation, lifestyle or settlement pattern for everyone.","recap":"Steep terrain and elevation shape access and land use, while technology, knowledge and community choices shape the response.","parentPrompt":"Discuss a fictional mountain settlement and list several possible solutions to one access problem instead of assuming one inevitable outcome."},
  "remediation":{"trigger":"Learner gives deterministic statements such as 'mountain people always do X' or lists challenges without considering adaptation.","strategy":"Rewrite four deterministic statements as evidence-based possibilities, then match each terrain challenge with two different human responses.","masteryEvidence":"Learner explains two mountain scenarios using terrain evidence, multiple possible adaptations and no livelihood or cultural stereotypes."}
},
{
  "id":"social-science.cbse6.exploring-society.ch3.plateaus-life.v1",
  "title":"Landforms and Life — Explore Plateaus and Resource Choices",
  "subject":"Social Science","worldId":"geography","topic":"CBSE Class 6 · Exploring Society: India and Beyond · Chapter 3","subtopic":"Plateaus, resources, farming, water and settlement","ageBand":"11-13","difficulty":"Foundational",
  "learningObjective":"Describe plateau characteristics and evaluate how elevation, soils, water, minerals and infrastructure can influence human activity without assuming every plateau has the same resources.",
  "content":"Plateaus are elevated landforms with broad surfaces that may be level, rolling or cut by rivers and valleys. Their human geography varies greatly. Some plateaus have mineral resources, some support farming or grazing, some contain forests or important river catchments, and others face water or soil constraints. Elevation can affect temperature and transport, while rivers may create valleys, waterfalls or hydroelectric opportunities in some places. None of these features is guaranteed simply because an area is a plateau. A sound geographic explanation combines physical evidence with local conditions and avoids the shortcut that all plateaus are mineral-rich or sparsely settled.",
  "workedExample":"Two fictional plateaus are the same height. Plateau A has reliable rainfall, deep soil and a road network; Plateau B has thin soil, seasonal water and no nearby transport link. Even with the same landform category, their farming, settlement and economic options can differ because additional conditions matter.",
  "board":"CBSE","classLevel":6,"curriculumSession":"2026-27","book":"Exploring Society: India and Beyond","chapter":3,"chapterTitle":"Landforms and Life","topicId":"TOPIC-SOC6-03-03","sourceRefs":["NCERT-EXPLORING-SOCIETY-G6-2026-27-CH3","KVS-CBSE6-SOC-CH3-SOURCE-TOPIC-V1"],"rightsStatus":"KIRTHIVERSE_ORIGINAL_NO_TEXTBOOK_PROSE_OR_EXERCISE_REPRODUCTION","schoolOverlay":"SAN Academy Tambaram","schoolMappingStatus":"VALIDATION_CONTEXT_ONLY_NO_SCHOOL_PACING_OR_EDITION_CLAIM",
  "kikiTeaching":{"objective":"Student explains a plateau using physical characteristics and evaluates more than one factor shaping human use.","intro":"Kiki treats 'plateau' as the start of the investigation, not the final answer about resources or livelihoods.","priorKnowledge":"Recall how a plateau differs broadly from a mountain and a plain.","visualIdea":"Use two same-height plateau cards with different soil, water and transport clues to show why landform alone is insufficient.","misconceptionCheck":"Not every plateau contains valuable minerals, and not every plateau supports the same farming or settlement pattern.","recap":"Plateaus are elevated broad landforms; local water, soil, resources, climate and connections shape how people use them.","parentPrompt":"Compare two fictional plateau profiles and ask which additional evidence is needed before recommending farming, mining or settlement."},
  "remediation":{"trigger":"Learner assumes a single plateau characteristic automatically predicts resources, occupation or population.","strategy":"Give four plateau profiles with different soil, rainfall, mineral and transport clues; require a conditional recommendation using 'could' and 'depends on'.","masteryEvidence":"Learner interprets three unfamiliar plateau scenarios and explains how at least three local factors interact with the landform category."}
},
{
  "id":"social-science.cbse6.exploring-society.ch3.plains-rivers-adaptation.v1",
  "title":"Landforms and Life — Connect Plains, Rivers and Adaptation",
  "subject":"Social Science","worldId":"geography","topic":"CBSE Class 6 · Exploring Society: India and Beyond · Chapter 3","subtopic":"Plains, rivers, settlement and flood-aware adaptation","ageBand":"11-13","difficulty":"Foundational",
  "learningObjective":"Explain why many plains support dense settlement and farming while recognising that river access, soil, flooding, climate and infrastructure create both benefits and risks.",
  "content":"Plains are broad areas of relatively low relief, and many are crossed by rivers or formed partly from river deposits. Gentle terrain can make roads, buildings and large fields easier to develop than in steep landscapes. Rivers can provide water, transport routes and fertile sediments, but they can also create flood risk. A plain is therefore not automatically safe, fertile or densely populated. Soil quality, rainfall, drainage, water management, climate, jobs, transport and public services all influence settlement and land use. People adapt through choices such as flood-aware building, drainage systems, embankments where appropriate, crop planning and keeping high-risk floodplain areas clear.",
  "workedExample":"A fictional riverside plain offers fertile soil and easy road access but floods every few years. A sensible settlement plan places essential services on safer ground, protects natural drainage, uses flood warnings and avoids putting the most vulnerable buildings in the highest-risk zone. The same river creates both opportunity and hazard.",
  "board":"CBSE","classLevel":6,"curriculumSession":"2026-27","book":"Exploring Society: India and Beyond","chapter":3,"chapterTitle":"Landforms and Life","topicId":"TOPIC-SOC6-03-04","sourceRefs":["NCERT-EXPLORING-SOCIETY-G6-2026-27-CH3","KVS-CBSE6-SOC-CH3-SOURCE-TOPIC-V1"],"rightsStatus":"KIRTHIVERSE_ORIGINAL_NO_TEXTBOOK_PROSE_OR_EXERCISE_REPRODUCTION","schoolOverlay":"SAN Academy Tambaram","schoolMappingStatus":"VALIDATION_CONTEXT_ONLY_NO_SCHOOL_PACING_OR_EDITION_CLAIM",
  "kikiTeaching":{"objective":"Student connects plain and river features to settlement opportunities, flood risks and practical adaptation choices.","intro":"Flat land can make building easier, but Kiki always asks what the water, soil and hazard evidence says too.","priorKnowledge":"Name one benefit and one risk of living near a river.","visualIdea":"Use a fictional river plain map with safe ground, flood-prone zones, farms, roads and services, then test alternative layouts.","misconceptionCheck":"Plains are not always fertile, rivers are not only beneficial, and dense settlement is not guaranteed by flat land alone.","recap":"Plains can support farming and settlement, while rivers bring resources and hazards that require informed adaptation.","parentPrompt":"Use a fictional floodplain sketch and ask the learner where to place a school, farm and clinic, explaining trade-offs without sharing a real address."},
  "remediation":{"trigger":"Learner treats flat terrain as automatically safe or fertile, or describes rivers only as benefits with no hazard awareness.","strategy":"Compare three fictional plains with different flood, soil and transport conditions; require one opportunity, one risk and one adaptation for each.","masteryEvidence":"Learner evaluates two unfamiliar plain-and-river scenarios and proposes justified settlement or land-use choices that balance opportunity, risk and adaptation."}
},
{
  "id":"social-science.cbse6.exploring-society.ch4.human-past.v1",
  "title":"Timeline and Sources of History — Investigate the Human Past",
  "subject":"Social Science","worldId":"geography","topic":"CBSE Class 6 · Exploring Society: India and Beyond · Chapter 4","subtopic":"Human past, historical questions and evidence","ageBand":"11-13","difficulty":"Foundational",
  "learningObjective":"Explain that history investigates the human past through evidence and compare how different specialists can contribute different kinds of information to a historical question.",
  "content":"History is an evidence-based investigation of the human past. Historians ask questions about people, events, ideas and changes, then examine surviving evidence before reaching conclusions. Other specialists can contribute different clues: archaeologists study material remains and sites; anthropologists can study human societies and cultures; geologists can help explain physical layers and landscapes; and palaeontologists study evidence of ancient life. These roles sometimes overlap, but they do not make every claim equally certain. A strong historical explanation states what the evidence directly shows, what can reasonably be inferred, and what remains unknown. One object, document or story rarely tells the whole history by itself, so responsible investigation compares evidence rather than treating the first clue as final proof.",
  "workedExample":"A fictional settlement site contains a broken storage pot, a stone tool and a later written inventory from a nearby town. The pot and tool are material evidence; the inventory is written evidence. Together they may support ideas about storage, tools or exchange, but they do not prove exactly who used every object or why. A careful historian separates observation from inference and notes what further evidence would strengthen the explanation.",
  "board":"CBSE","classLevel":6,"curriculumSession":"2026-27","book":"Exploring Society: India and Beyond","chapter":4,"chapterTitle":"Timeline and Sources of History","topicId":"TOPIC-SOC6-04-01","sourceRefs":["NCERT-EXPLORING-SOCIETY-G6-2026-27-CH4","KVS-CBSE6-SOC-CH4-SOURCE-TOPIC-V1"],"rightsStatus":"KIRTHIVERSE_ORIGINAL_NO_TEXTBOOK_PROSE_OR_EXERCISE_REPRODUCTION","schoolOverlay":"SAN Academy Tambaram","schoolMappingStatus":"VALIDATION_CONTEXT_ONLY_NO_SCHOOL_PACING_OR_EDITION_CLAIM",
  "kikiTeaching":{"objective":"Student distinguishes evidence, inference and uncertainty when investigating a simple question about the human past.","intro":"Kiki approaches the past like an evidence puzzle: first ask a question, then inspect clues, compare them and say only what the evidence supports.","priorKnowledge":"Give one example of an object, written record or other trace that could tell us something about an earlier time.","visualIdea":"Use a three-column evidence board labelled observation, reasonable inference and still unknown.","misconceptionCheck":"History is not simply guessing about old times, and one surviving source does not automatically prove the whole story.","recap":"Historical knowledge is built by asking questions, examining evidence, comparing sources and keeping uncertainty visible.","parentPrompt":"Use fictional source cards or public museum-style examples. Do not ask the learner to reveal private family stories, religion, caste, community identity, photographs or recordings."},
  "remediation":{"trigger":"Learner treats an inference as a directly observed fact or assumes one source gives a complete account.","strategy":"Give four fictional evidence cards and require the learner to label each statement as observation, supported inference or unsupported claim, then identify one additional source that could test the inference.","masteryEvidence":"Learner analyses two unfamiliar historical evidence sets and clearly separates what is observed, what is reasonably inferred and what remains uncertain."}
},
{
  "id":"social-science.cbse6.exploring-society.ch4.historical-time.v1",
  "title":"Timeline and Sources of History — Reason with Historical Time",
  "subject":"Social Science","worldId":"geography","topic":"CBSE Class 6 · Exploring Society: India and Beyond · Chapter 4","subtopic":"Chronology, timelines, BCE, CE, decades, centuries and millennia","ageBand":"11-13","difficulty":"Foundational",
  "learningObjective":"Use chronology and timelines to order events and interpret BCE, CE, decade, century and millennium at an introductory Class 6 level.",
  "content":"Chronology means arranging events in time order. Timelines help us see what happened earlier, what happened later and how far apart periods may be. Historians commonly use BCE for years before the Common Era and CE for years in the Common Era. In BCE, larger year numbers are farther back in the past, so 800 BCE is earlier than 300 BCE. In CE, larger numbers are later, so 1200 CE is later than 900 CE. A decade is ten years, a century is one hundred years and a millennium is one thousand years. These units help organise long spans without turning history into date memorisation. When a timeline crosses from BCE to CE, learners should focus first on correct order and interval reasoning; there is no year zero in the conventional BCE/CE calendar sequence.",
  "workedExample":"Four fictional events are dated 700 BCE, 250 BCE, 400 CE and 900 CE. In chronological order from earliest to latest they are 700 BCE, 250 BCE, 400 CE and 900 CE. The BCE numbers decrease as time moves toward the Common Era, while CE numbers increase as time moves forward.",
  "board":"CBSE","classLevel":6,"curriculumSession":"2026-27","book":"Exploring Society: India and Beyond","chapter":4,"chapterTitle":"Timeline and Sources of History","topicId":"TOPIC-SOC6-04-02","sourceRefs":["NCERT-EXPLORING-SOCIETY-G6-2026-27-CH4","KVS-CBSE6-SOC-CH4-SOURCE-TOPIC-V1"],"rightsStatus":"KIRTHIVERSE_ORIGINAL_NO_TEXTBOOK_PROSE_OR_EXERCISE_REPRODUCTION","schoolOverlay":"SAN Academy Tambaram","schoolMappingStatus":"VALIDATION_CONTEXT_ONLY_NO_SCHOOL_PACING_OR_EDITION_CLAIM",
  "kikiTeaching":{"objective":"Student places unfamiliar BCE and CE dates in chronological order and explains decade, century and millennium without reversing BCE order.","intro":"Kiki treats a timeline as a number line for the past, but BCE needs one special check: bigger BCE numbers are farther back in time.","priorKnowledge":"Arrange four ordinary dates or ages from earlier to later and explain the ordering rule.","visualIdea":"Use one horizontal timeline with BCE on the left and CE on the right, marking earlier and later arrows plus decade, century and millennium scale cards.","misconceptionCheck":"800 BCE is earlier than 300 BCE even though 800 is the larger number, and the conventional BCE/CE sequence has no year zero.","recap":"Chronology orders events; BCE counts back from the Common Era, CE moves forward, and decades, centuries and millennia organise longer spans.","parentPrompt":"Use invented historical dates on paper and ask the learner to order them. No personal or family dates are required."},
  "remediation":{"trigger":"Learner reverses BCE order, confuses a century with one hundred specific calendar years, or treats BCE and CE as unrelated timelines.","strategy":"Sort ten fictional date cards on one continuous timeline, first separating BCE from CE, then ordering each side and labelling examples of a decade, century and millennium.","masteryEvidence":"Learner correctly orders mixed BCE/CE date sets, explains why BCE ordering appears reversed numerically, and uses decade, century and millennium accurately in unfamiliar examples."}
},
{
  "id":"social-science.cbse6.exploring-society.ch4.sources-evidence.v1",
  "title":"Timeline and Sources of History — Evaluate Historical Sources",
  "subject":"Social Science","worldId":"geography","topic":"CBSE Class 6 · Exploring Society: India and Beyond · Chapter 4","subtopic":"Material, written, oral and other historical evidence","ageBand":"11-13","difficulty":"Foundational",
  "learningObjective":"Compare broad categories of historical sources and use corroboration to decide whether an inference is well supported, weakly supported or still uncertain.",
  "content":"Historical sources are traces of the past that can provide evidence. Material or archaeological evidence includes objects, buildings, tools, coins and other physical remains. Written or literary evidence can include inscriptions, letters, records and other texts. Oral evidence and remembered traditions can also preserve information, while images and other records may add further clues. Each source has strengths and limits: an object may show that something existed without explaining every use; a written record may reflect the viewpoint or purpose of its creator; an oral account may preserve valuable memory while changing across retellings. Historians therefore corroborate, which means comparing independent evidence to see where it agrees, differs or leaves gaps. Responsible interpretation does not turn a single clue into certainty when alternatives remain possible.",
  "workedExample":"A fictional market site has a group of coins, a damaged account tablet and a traveller's later description. All three suggest exchange took place, but they answer different questions and may come from different times. Agreement across independent evidence can strengthen an inference, while contradictions require more investigation rather than choosing the most convenient source.",
  "board":"CBSE","classLevel":6,"curriculumSession":"2026-27","book":"Exploring Society: India and Beyond","chapter":4,"chapterTitle":"Timeline and Sources of History","topicId":"TOPIC-SOC6-04-03","sourceRefs":["NCERT-EXPLORING-SOCIETY-G6-2026-27-CH4","KVS-CBSE6-SOC-CH4-SOURCE-TOPIC-V1"],"rightsStatus":"KIRTHIVERSE_ORIGINAL_NO_TEXTBOOK_PROSE_OR_EXERCISE_REPRODUCTION","schoolOverlay":"SAN Academy Tambaram","schoolMappingStatus":"VALIDATION_CONTEXT_ONLY_NO_SCHOOL_PACING_OR_EDITION_CLAIM",
  "kikiTeaching":{"objective":"Student classifies source types, identifies one limitation and uses corroboration before making a historical inference.","intro":"Kiki never asks only, 'What does this source say?' The next questions are, 'What kind of source is it, what can it support, and what other evidence agrees or disagrees?'","priorKnowledge":"Explain why two witnesses or records can describe the same event differently without one automatically being useless.","visualIdea":"Use three fictional source cards feeding into a corroboration triangle: agreement, difference and missing evidence.","misconceptionCheck":"One source does not automatically prove a complete historical account; source type, purpose, context and corroboration matter.","recap":"Historical sources provide evidence with limits, and corroboration strengthens or challenges interpretations.","parentPrompt":"Use fictional documents, artefact sketches or rights-safe public examples. Do not require private family records, identity details, photos or recordings."},
  "remediation":{"trigger":"Learner labels a source category correctly but accepts every claim from it without checking context, limitations or other evidence.","strategy":"Provide three fictional sources about one event, including one disagreement. Ask what each source supports, what it cannot establish alone and what additional evidence would help.","masteryEvidence":"Learner evaluates an unfamiliar three-source set, classifies each source, identifies limitations and produces a cautious conclusion supported by corroboration."}
},
{
  "id":"social-science.cbse6.exploring-society.ch4.early-communities-change.v1",
  "title":"Timeline and Sources of History — Trace Change in Early Communities",
  "subject":"Social Science","worldId":"geography","topic":"CBSE Class 6 · Exploring Society: India and Beyond · Chapter 4","subtopic":"Early communities, evidence, continuity and change","ageBand":"11-13","difficulty":"Foundational",
  "learningObjective":"Use simple evidence sets to reason cautiously about changes in early human communities over long periods without making unsupported claims about ancestry, identity or exact migration histories.",
  "content":"Evidence from tools, food remains, shelters, hearths, settlement traces and other material finds can help historians and archaeologists reason about how early human communities lived and changed. Different groups at different times may have relied on gathering, hunting, fishing, herding, cultivation or combinations of activities. Some communities were more mobile while others stayed longer in particular places, and patterns could change gradually as environments, knowledge, resources and social choices changed. Evidence rarely reveals every detail, so a careful explanation uses phrases such as 'the evidence suggests' or 'one reasonable interpretation is'. This introductory topic does not require advanced dating methods, genetics, ancient DNA or claims about a learner's ancestry or community identity. The goal is to recognise continuity and change while keeping uncertainty visible.",
  "workedExample":"At two fictional sites from different periods, Site A contains portable tools and short-lived hearth traces, while Site B has repeated building foundations, storage pits and cultivation evidence. These clues may support an inference that Site B involved longer-term settlement, but they do not prove that every person stayed permanently or reveal a precise ancestry or migration route.",
  "board":"CBSE","classLevel":6,"curriculumSession":"2026-27","book":"Exploring Society: India and Beyond","chapter":4,"chapterTitle":"Timeline and Sources of History","topicId":"TOPIC-SOC6-04-04","sourceRefs":["NCERT-EXPLORING-SOCIETY-G6-2026-27-CH4","KVS-CBSE6-SOC-CH4-SOURCE-TOPIC-V1"],"rightsStatus":"KIRTHIVERSE_ORIGINAL_NO_TEXTBOOK_PROSE_OR_EXERCISE_REPRODUCTION","schoolOverlay":"SAN Academy Tambaram","schoolMappingStatus":"VALIDATION_CONTEXT_ONLY_NO_SCHOOL_PACING_OR_EDITION_CLAIM",
  "kikiTeaching":{"objective":"Student compares early-community evidence, identifies continuity and change, and states conclusions with appropriate uncertainty.","intro":"Kiki asks what changed, what may have stayed similar, and how strongly the surviving evidence supports each idea.","priorKnowledge":"Compare two fictional scenes and identify one feature that changed and one that stayed similar.","visualIdea":"Use two evidence panels from different periods linked by arrows labelled continuity, change and uncertain.","misconceptionCheck":"A few artefacts cannot reveal exact ancestry, identity or migration routes, and one evidence pattern does not mean every early community lived the same way.","recap":"Material evidence can suggest how communities changed over time, but interpretations must stay proportional to the evidence and acknowledge uncertainty.","parentPrompt":"Use fictional site cards or public archaeology-style examples. Do not ask about the learner's ancestry, caste, religion, community identity or family history."},
  "remediation":{"trigger":"Learner turns a possible interpretation into certainty or assumes all early communities followed one identical sequence of change.","strategy":"Compare two fictional site evidence sets and require three labels: directly observed, reasonable inference and still uncertain. Then write two alternative explanations for one ambiguous clue.","masteryEvidence":"Learner compares unfamiliar early-community evidence, identifies continuity and change, offers a supported interpretation and names at least one uncertainty or alternative explanation."}
}
);